messages.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.VideoUrl",
  "description": "A video URL for multimodal input.",
  "type": "object",
  "properties": {
    "url": {
      "description": "The URL of the video.",
      "type": "string"
    }
  },
  "required": [
    "url"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.SimpleContentPartExpression",
  "description": "Expression variant of [`SimpleContentPart`] for dynamic content.",
  "oneOf": [
    {
      "description": "A text part expression.",
      "type": "object",
      "properties": {
        "text": {
          "description": "The text expression.",
          "$ref": "functions.expression.WithExpression.string"
        },
        "type": {
          "type": "string",
          "const": "text"
        }
      },
      "required": [
        "type",
        "text"
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.ImageUrl",
  "description": "An image URL for multimodal input.",
  "type": "object",
  "properties": {
    "url": {
      "description": "The URL of the image (can be a data URL or HTTP URL).",
      "type": "string"
    },
    "detail": {
      "description": "The detail level for image processing.",
      "anyOf": [
        {
          "$ref": "agent.completions.message.ImageUrlDetail"
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "url"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.SimpleContentPartExpression",
  "description": "Expression variant of [`SimpleContentPart`] for dynamic content.",
  "oneOf": [
    {
      "description": "A text part expression.",
      "type": "object",
      "properties": {
        "text": {
          "description": "The text expression.",
          "$ref": "functions.expression.WithExpression.string"
        },
        "type": {
          "type": "string",
          "const": "text"
        }
      },
      "required": [
        "type",
        "text"
      ]
    }
  ]
}
